/// Trusted bridge injected after publication sanitization. Package scripts never
/// receive a nonce. Positions use the same UTF-16 text order as native EPUB.
const webReaderScript = r'''
'use strict';
(()=>{
const config=JSON.parse(document.currentScript.dataset.config),parentOrigin=location.origin;
let restoring=true,timer,selected=null,sequence=0;
const nodes=()=>{const out=[],w=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentElement?.closest('script,style,noscript')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});let n;while((n=w.nextNode())){out.push(n);if(out.length>250000)break;}return out;};
const emit=(type,data={})=>parent.postMessage({channel:'tangerine.reader',request:config.request,item:config.item,revision:config.revision,key:config.key,type,...data},parentOrigin);
function offset(node,index){let sum=0;for(const n of nodes()){if(n===node)return sum+Math.min(index,n.length);sum+=n.length;}return null;}
function point(index){let left=Math.max(0,index);const all=nodes();for(const n of all){if(left<=n.length)return[n,left];left-=n.length;}const last=all.at(-1);return last?[last,last.length]:null;}
function atViewport(){const x=Math.min(innerWidth-1,Math.max(1,innerWidth*.4)),y=Math.min(innerHeight-1,Math.max(1,innerHeight*.2));let node,index;if(document.caretPositionFromPoint){const p=document.caretPositionFromPoint(x,y);node=p?.offsetNode;index=p?.offset;}else if(document.caretRangeFromPoint){const r=document.caretRangeFromPoint(x,y);node=r?.startContainer;index=r?.startOffset;}const start=node?.nodeType===Node.TEXT_NODE?offset(node,index):null;const text=start==null?'':nodes().map(n=>n.data).join('').slice(start,start+120);return {textOffset:start,textQuote:text,x:(scrollX+innerWidth*.5)/Math.max(innerWidth,document.documentElement.scrollWidth),y:(scrollY+innerHeight*.2)/Math.max(innerHeight,document.documentElement.scrollHeight),textBias:.2};}
function capture(captureId){if(!restoring)emit('position',{...atViewport(),captureId});}
function restore(data){restoring=true;const all=nodes(),text=all.map(n=>n.data).join('');let start=Number.isInteger(data.textOffset)?data.textOffset:null;if(data.textQuote&&text.slice(start,start+data.textQuote.length)!==data.textQuote){const found=text.indexOf(data.textQuote);if(found>=0)start=found;}let target=start==null?null:point(start);if(target){const range=document.createRange();range.setStart(...target);range.setEnd(...target);const rect=range.getBoundingClientRect();scrollBy(0,rect.top-innerHeight*(data.textBias??.2));if(data.endOffset>start){const end=point(data.endOffset);if(end){range.setEnd(...end);const sel=getSelection();sel.removeAllRanges();sel.addRange(range);}}}else if(data.fragment){document.getElementById(data.fragment)?.scrollIntoView();}else scrollTo((data.x||0)*document.documentElement.scrollWidth-innerWidth*.5,(data.y||0)*document.documentElement.scrollHeight-innerHeight*.2);const token=++sequence;setTimeout(()=>{if(token===sequence){restoring=false;emit('ready',{height:document.documentElement.scrollHeight,width:document.documentElement.scrollWidth});}},200);}
addEventListener('message',async e=>{if(e.source!==parent||e.origin!==parentOrigin||e.data?.channel!=='tangerine.reader'||e.data.request!==config.request)return;const data=e.data;if(data.type==='configure'){if(data.reflowable){document.documentElement.style.setProperty('font-size',Math.max(12,Math.min(40,data.font||18))+'px');document.body.style.fontSize='inherit';document.body.style.lineHeight=String(Math.max(1,Math.min(2.5,data.line||1.6)));document.body.style.maxWidth='75ch';document.body.style.margin='auto';document.body.style.padding='20px';}await document.fonts.ready;requestAnimationFrame(()=>restore(data.locator||{}));}if(data.type==='capture')capture(data.captureId);if(data.type==='restore')restore(data.locator||{});});
addEventListener('scroll',()=>{clearTimeout(timer);timer=setTimeout(capture,150);},{passive:true});
document.addEventListener('selectionchange',()=>{clearTimeout(selected);selected=setTimeout(()=>{const s=getSelection();if(!s||s.isCollapsed||!s.rangeCount){emit('selection',{selection:null});return;}const r=s.getRangeAt(0),start=offset(r.startContainer,r.startOffset),end=offset(r.endContainer,r.endOffset);if(start!=null&&end>start)emit('selection',{selection:{start,end,quote:s.toString().slice(0,16000)}});},120);});
document.addEventListener('click',e=>{const link=e.target.closest?.('a');if(!link)return;e.preventDefault();try{const raw=link.getAttribute('href')||'';if(raw.startsWith('#')){emit('link',{path:config.key,fragment:decodeURIComponent(raw.slice(1))});return;}const url=new URL(link.href,location.href);if(url.origin===location.origin&&url.pathname.startsWith(config.prefix))emit('link',{path:decodeURIComponent(url.pathname.slice(config.prefix.length)),fragment:decodeURIComponent(url.hash.slice(1))});}catch{}});
const sheet=document.createElement('style');sheet.textContent='html{scroll-behavior:auto}body{overflow-wrap:anywhere}img,svg{max-width:100%;height:auto}';document.head?.append(sheet);
